import{_ as s,l as r,o as e,c as n,v as t,p as l,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"DNS 缓存投毒","description":"","frontmatter":{"title":"DNS 缓存投毒","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns-cache-poisoning.md","filePath":"cs/dns-cache-poisoning.md","lastUpdated":1789023840000}'),c={name:"cs/dns-cache-poisoning.md"};function A(E,a,S,D,_,m){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="dns-缓存投毒" tabindex="-1">DNS 缓存投毒 <a class="header-anchor" href="#dns-缓存投毒" aria-label="Permalink to &quot;DNS 缓存投毒&quot;">​</a></h1><div class="epigraph"><p>解析器若把错误的 A 记录缓存起来，随后的 TLS 会连到攻击者的 IP——证书验证仍可能失败，但用户会看到错误页或被诱去关校验。投毒打的是名称到地址的映射，不是 AES。</p><footer>—— 据 Kaminsky 对缓存投毒的公开分析；RFC 5452；RFC 4033 DNSSEC</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/wpa2-wpa3">WPA</a>保护最后一跳。缺口是<strong>名字</strong>：应用信任主机名，IP 来自 DNS。主干<a href="/cs/dns">DNS</a>已有查询。本课收缓存污染与事务端口/ID 随机化，以及 DNSSEC 的真假。不给投毒操作程序。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>递归解析器接受一条伪造应答并缓存，TTL 期内全网客户被指向错 IP。Kaminsky：扩大碰撞面。防御：源端口随机、DNSSEC 验签、DoT/DoH 对路径保密。缺口是解析信任，不是再讲记录类型。</p><h3 id="tls-仍要验名" tabindex="-1">TLS 仍要验名 <a class="header-anchor" href="#tls-仍要验名" aria-label="Permalink to &quot;TLS 仍要验名&quot;">​</a></h3><p>投毒后证书名不匹配应失败。用户点「继续」才把投毒兑现成保密失败。</p><p><span class="marginnote">RFC 5452 随机化。DNSSEC 验的是区签名链，部署不完整。本课禁止写伪造应答的实验指导。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画查询 ID 与端口的匹配窗口。对照：路径加密（DoH）防窃听与部分篡改，但不自动给端到端区真实性——那是 DNSSEC。应用应钉证书或 DANE（点名即可）。</p>',12)),(e(),l(p,null,{default:o(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20CACHE%5B%22%E9%80%92%E5%BD%92%E7%BC%93%E5%AD%98%22%5D%0A%20%20FAKE%5B%22%E4%BC%AA%E9%80%A0%E5%BA%94%E7%AD%94%22%5D%20--%3E%20CACHE%0A%20%20CACHE%20--%3E%20IP%5B%22%E9%94%99%E8%AF%AF%20IP%22%5D%0A%20%20DNSSEC%5B%22DNSSEC%22%5D%20--%3E%20V%5B%22%E9%AA%8C%E7%AD%BE%E5%88%99%E6%8B%92%E5%81%87%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>身份链从证书回退到名字，名字回退到解析。下一课 ARP：同一局域网里更短的映射，IP 到 MAC。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部 Kaminsky 变体写成菜谱。ARP 欺骗下一课：二层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无线之后，名字解析是下一跳信任。</li><li>缓存投毒污染 A/AAAA；TLS 名检查是安全带。</li><li>随机化、DNSSEC、加密传输分层补。</li><li>下一课 ARP 欺骗。</li><li>出处：RFC 5452；RFC 4033；Kaminsky（作为历史分析点名）。</li></ul>',8))])}const P=s(c,[["render",A]]);export{u as __pageData,P as default};
